"use client";

import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  cupGroupName,
  summarizeCupGroup,
} from "@/features/nba-cup/nba-cup-schema";
import { ScrollArea } from "@/components/ui/scroll-area";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import type {
  CupGroup,
  CupGroupData,
  CupTeam,
} from "@/features/nba-cup/nba-cup-schema";

export type NbaCupCardState = "streaming" | "loading" | "ready" | "error";

export interface NbaCupCardProperties {
  readonly state: NbaCupCardState;
  /**
  The group from the props, shown before the data arrives.
  */
  readonly group?: CupGroup;
  readonly data?: CupGroupData;
  readonly error?: string;
  readonly className?: string;
}

/**
One plain surface for the whole card. The table scrolls sideways when the card is narrower than its columns.
*/
const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-[640px]`;

const MUTED = "text-muted-foreground";

const STAT = "text-center whitespace-nowrap tabular-nums";

/**
The stat columns after the team, left to right, as the NBA lays out a Cup group.
*/
const COLUMNS = [
  {
    label: "GP",
    title: "Games played",
    value: (team: CupTeam) => team.wins + team.losses,
  },
  { label: "W", title: "Wins", value: (team: CupTeam) => team.wins },
  { label: "L", title: "Losses", value: (team: CupTeam) => team.losses },
  {
    label: "Pts+",
    title: "Points scored",
    value: (team: CupTeam) => team.pointsFor,
  },
  {
    label: "Pts-",
    title: "Points allowed",
    value: (team: CupTeam) => team.pointsAgainst,
  },
  {
    label: "Diff",
    title: "Point difference",
    value: (team: CupTeam) => team.difference,
  },
] as const;

const TEAMS_PER_GROUP = 5;

/**
One of the logo's two images: the light one, or the one the NBA draws for dark backgrounds. The theme hides the other.
*/
const LogoImage = ({
  src,
  onError,
  className,
}: {
  readonly src: string;
  readonly onError: () => void;
  readonly className: string;
}) => (
  // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the logo host into the installer's next.config; onError swaps in the letters, it is not a user interaction
  <img
    src={src}
    alt=""
    width={24}
    height={24}
    loading="lazy"
    onError={onError}
    className={cn("size-6 object-contain", className)}
  />
);

const TeamLogo = ({ team }: { readonly team: CupTeam }) => {
  const [failed, setFailed] = useState(false);
  if (failed) {
    return (
      <span
        aria-hidden
        className="flex size-6 shrink-0 items-center justify-center text-[10px]"
      >
        {team.abbreviation}
      </span>
    );
  }
  return (
    <span aria-hidden className="flex size-6 shrink-0">
      <LogoImage
        src={team.logo}
        onError={() => setFailed(true)}
        className="dark:hidden"
      />
      <LogoImage
        src={team.logoDark}
        onError={() => setFailed(true)}
        className="hidden dark:block"
      />
    </span>
  );
};

const Header = ({
  group,
  season,
}: {
  readonly group: CupGroup;
  readonly season?: string;
}) => (
  <header className="flex items-center justify-between gap-3 text-sm">
    <p className="min-w-0 truncate">
      <span className="text-blue-600 dark:text-blue-400">NBA Cup</span>
      <span className={MUTED}> · {cupGroupName(group)}</span>
    </p>
    {season ? (
      <p className={cn(MUTED, "shrink-0 tabular-nums")}>{season}</p>
    ) : null}
  </header>
);

const GroupTable = ({ data }: { readonly data: CupGroupData }) => (
  <ScrollArea orientation="horizontal" className="-mx-1">
    <Table className="min-w-[440px] text-sm">
      <caption className="sr-only">
        NBA Cup {cupGroupName(data.group)}, {data.season}
      </caption>
      <TableHeader>
        <TableRow>
          <TableHead scope="col">Team</TableHead>
          {COLUMNS.map((column) => (
            <TableHead key={column.label} scope="col" className={STAT}>
              <abbr title={column.title} className="no-underline">
                {column.label}
              </abbr>
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {data.teams.map((team, index) => (
          <TableRow key={team.abbreviation} index={index}>
            <TableCell>
              <span className="flex min-w-0 items-center gap-3">
                <span className="w-5 shrink-0 text-right tabular-nums">
                  {team.rank}
                </span>
                <TeamLogo team={team} />
                <span className="truncate whitespace-nowrap">{team.name}</span>
              </span>
            </TableCell>
            {COLUMNS.map((column) => (
              <TableCell key={column.label} className={STAT}>
                {column.value(team)}
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  </ScrollArea>
);

const NbaCupError = ({
  group,
  message = "The NBA's stats service didn't respond. Try again in a moment.",
}: {
  readonly group?: CupGroup;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {group
        ? `Couldn't load NBA Cup ${cupGroupName(group)}`
        : "Couldn't load the NBA Cup"}
    </p>
    <p className={cn(MUTED, "text-xs")}>{message}</p>
  </div>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <div className={cn("bg-muted animate-pulse rounded", className)} />
);

const SKELETON_ROWS = Array.from(
  { length: TEAMS_PER_GROUP },
  (_, index) => `row-${index + 1}`
);

/**
The card while its data is on the way: the same header and one row per team at the table's height, so nothing moves when the table lands.
*/
export const NbaCupCardSkeleton = ({
  group,
  className,
}: {
  readonly group?: CupGroup;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "block", className)}>
    <span className="sr-only">
      {group ? `Loading NBA Cup ${cupGroupName(group)}` : "Loading the NBA Cup"}
    </span>
    <div aria-hidden className="flex flex-col gap-3">
      {group ? (
        <Header group={group} />
      ) : (
        <div className="flex h-5 items-center">
          <Bar className="h-3.5 w-40" />
        </div>
      )}
      <div className="flex flex-col">
        {/* The header row and each team row are 37px: 36 on the ladder plus a 1px rule. */}
        <div className="flex h-[37px] items-center px-3">
          <Bar className="h-3.5 w-12" />
        </div>
        {SKELETON_ROWS.map((row) => (
          <div key={row} className="flex h-[37px] items-center gap-3 px-3">
            <Bar className="size-6 rounded-full" />
            <Bar className="h-3.5 w-28" />
          </div>
        ))}
      </div>
    </div>
  </output>
);

export default function NbaCupCard({
  state,
  group,
  data,
  error,
  className,
}: NbaCupCardProperties) {
  if (state === "ready" && data) {
    return (
      <section
        aria-label={summarizeCupGroup(data)}
        className={cn(CARD_FRAME, "flex flex-col gap-3", className)}
      >
        <Header group={data.group} season={data.season} />
        <GroupTable data={data} />
      </section>
    );
  }
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <NbaCupError group={group} message={error} />
      </div>
    );
  }
  return <NbaCupCardSkeleton group={group} className={className} />;
}

"use client";

import { useEffect, useState } from "react";
import NbaCupCard from "@/features/nba-cup/components/nba-cup-card";
import { loadCupGroup } from "@/features/nba-cup/nba-cup-requests";
import { errorMessage, parseCupGroup } from "@/features/nba-cup/nba-cup-schema";
import type { CupGroupData } from "@/features/nba-cup/nba-cup-schema";

/**
What came back for one group. A result for another group reads as still loading, so the card never flashes the wrong table.
*/
type Result =
  | { key: string; status: "ready"; data: CupGroupData }
  | { key: string; status: "error"; message: string };

export default function LiveNbaCupCard({
  group: requested,
  streaming = false,
  className,
}: {
  /**
  e.g. "west-a"; anything else waits.
  */
  readonly group?: string;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [result, setResult] = useState<Result | null>(null);
  const group = requested ? parseCupGroup(requested) : null;

  useEffect(() => {
    let isCancelled = false;
    const run = async () => {
      if (!group) {
        return;
      }
      let next: Result;
      try {
        next = { data: await loadCupGroup(group), key: group, status: "ready" };
      } catch (error) {
        next = {
          key: group,
          message: errorMessage(error, "NBA Cup lookup failed."),
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming) {
      run();
    }
    return () => {
      isCancelled = true;
    };
  }, [group, streaming]);

  if (streaming || !group) {
    return (
      <NbaCupCard
        state="streaming"
        group={group ?? undefined}
        className={className}
      />
    );
  }
  const current = result?.key === group ? result : null;
  if (current?.status === "ready") {
    return (
      <NbaCupCard state="ready" data={current.data} className={className} />
    );
  }
  if (current?.status === "error") {
    return (
      <NbaCupCard
        state="error"
        group={group}
        error={current.message}
        className={className}
      />
    );
  }
  return <NbaCupCard state="loading" group={group} className={className} />;
}

import { z } from "zod";
import { CUP_GROUPS } from "@/features/nba-cup/nba-cup-schema";

export const nbaCupCatalogEntry = {
  description:
    "One NBA Cup group's table this season: its five teams in order, with games played, wins, losses, points for and against, and the point difference. It fetches its own data. Use it whenever the user asks about the NBA Cup (also called the In-Season Tournament), its group stage, or a Cup group. For one group (\"West Group A\"), show that group. For a conference's Cup groups, show its three in a CardGroup, A first. For the whole NBA Cup, show all six in a CardGroup: East A, B, C, then West A, B, C. For one team's Cup group, show the group it plays in.",
  props: z.object({
    group: z
      .enum(CUP_GROUPS)
      .describe(
        'The group: "east-a", "east-b" or "east-c" in the East, "west-a", "west-b" or "west-c" in the West.'
      ),
  }),
};

import { listOf } from "@/features/chat/lookup";
import { loadCupGroup } from "@/features/nba-cup/nba-cup-requests";
import { cupGroupName, parseCupGroup } from "@/features/nba-cup/nba-cup-schema";
import type { CardLookup } from "@/features/chat/lookup";

function groupOf(properties: Record<string, unknown>) {
  return typeof properties.group === "string"
    ? parseCupGroup(properties.group)
    : null;
}

export const nbaCupLookup: CardLookup = {
  intent: (groups) => `The NBA Cup's ${listOf(groups)}`,
  load: async (properties) => {
    const group = groupOf(properties);
    if (!group) {
      throw new Error("Pick an NBA Cup group, e.g. west-a.");
    }
    return await loadCupGroup(group);
  },
  sources: () => [
    {
      href: "https://www.nba.com/cup/standings",
      label: "nba.com/cup/standings",
    },
  ],
  subject: (properties) => {
    const group = groupOf(properties);
    return group ? cupGroupName(group) : null;
  },
};

import type { CupGroup, CupGroupData } from "@/features/nba-cup/nba-cup-schema";

const sharedCupRequests = new Map<
  CupGroup,
  { expiresAt: number; table: Promise<CupGroupData> }
>();
/**
A group's table moves once one of its games ends, so a minute is fresh enough.
*/
const REUSE_MS = 60_000;

async function fetchCupGroup(group: CupGroup) {
  const response = await fetch(`/api/nba-cup?group=${group}`);
  const body = (await response.json()) as CupGroupData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `NBA Cup request failed: ${response.status}`
    );
  }
  return body;
}

async function requestCupGroup(group: CupGroup) {
  try {
    return await fetchCupGroup(group);
  } catch (error) {
    sharedCupRequests.delete(group);
    throw error;
  }
}

export function loadCupGroup(group: CupGroup) {
  const hit = sharedCupRequests.get(group);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.table;
  }
  const table = requestCupGroup(group);
  sharedCupRequests.set(group, { expiresAt: Date.now() + REUSE_MS, table });
  return table;
}

export function primeCupGroup(group: CupGroup, data: CupGroupData) {
  sharedCupRequests.set(group, {
    expiresAt: Infinity,
    table: Promise.resolve(data),
  });
}

import "server-only";
import { cupGroupName } from "@/features/nba-cup/nba-cup-schema";
import type {
  CupGroup,
  CupGroupData,
  CupTeam,
} from "@/features/nba-cup/nba-cup-schema";

// Server only: the NBA's stats API doesn't allow browser requests (CORS).

const IST_STANDINGS = "https://stats.nba.com/stats/iststandings";

/**
The NBA's stats API leaves a request hanging unless it looks like it came from nba.com.
*/
const HEADERS = {
  Accept: "application/json, text/plain, */*",
  Origin: "https://www.nba.com",
  Referer: "https://www.nba.com/",
  "User-Agent":
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36",
  "x-nba-stats-origin": "stats",
  "x-nba-stats-token": "true",
};

const TIMEOUT_MS = 10_000;
/**
One answer holds all six groups, so the card for each group reuses it.
*/
const FRESH_MS = 60_000;

interface IstTeam {
  teamId: number;
  teamName: string;
  teamAbbreviation: string;
  istGroup: string;
  istGroupRank: number;
  wins: number;
  losses: number;
  pts: number;
  oppPts: number;
  diff: number;
}

interface IstStandings {
  seasonYear: string;
  teams?: IstTeam[];
}

/**
The season the NBA Cup is in: from August on, the one starting that fall, so "2026-27" in October 2026.
*/
function currentSeason(now = new Date()) {
  const AUGUST = 7;
  const start =
    now.getUTCMonth() >= AUGUST
      ? now.getUTCFullYear()
      : now.getUTCFullYear() - 1;
  return `${start}-${String((start + 1) % 100).padStart(2, "0")}`;
}

const cache: {
  current: { expiresAt: number; standings: Promise<IstStandings> } | null;
} = { current: null };

async function fetchStandings(season: string) {
  const parameters = new URLSearchParams({
    LeagueID: "00",
    Season: season,
    Section: "group",
  });
  const response = await fetch(`${IST_STANDINGS}?${parameters}`, {
    headers: HEADERS,
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`The NBA's stats service returned ${response.status}.`);
  }
  return (await response.json()) as IstStandings;
}

async function standingsOf(season: string) {
  try {
    return await fetchStandings(season);
  } catch (error) {
    cache.current = null;
    throw error;
  }
}

function cupStandings() {
  const hit = cache.current;
  if (hit && Date.now() < hit.expiresAt) {
    return hit.standings;
  }
  const standings = standingsOf(currentSeason());
  cache.current = { expiresAt: Date.now() + FRESH_MS, standings };
  return standings;
}

/**
ESPN's logo names where they differ from the NBA's abbreviation. ESPN's logo host answers every client; the NBA's own refuses requests it takes for bots.
*/
const ESPN_LOGO_NAME: Record<string, string> = {
  GSW: "gs",
  NOP: "no",
  NYK: "ny",
  SAS: "sa",
  UTA: "utah",
  WAS: "wsh",
};

function teamOf(team: IstTeam): CupTeam {
  const logo =
    ESPN_LOGO_NAME[team.teamAbbreviation] ??
    team.teamAbbreviation.toLowerCase();
  return {
    abbreviation: team.teamAbbreviation,
    difference: team.diff,
    logo: `https://a.espncdn.com/i/teamlogos/nba/500/scoreboard/${logo}.png`,
    logoDark: `https://a.espncdn.com/i/teamlogos/nba/500-dark/scoreboard/${logo}.png`,
    losses: team.losses,
    name: team.teamName,
    pointsAgainst: team.oppPts,
    pointsFor: team.pts,
    rank: team.istGroupRank,
    wins: team.wins,
  };
}

/**
One NBA Cup group's table this season, first place first, in the NBA's own order (its tiebreakers settle ties, and the order before any game is played).
*/
export async function getCupGroup(group: CupGroup): Promise<CupGroupData> {
  const standings = await cupStandings();
  const name = cupGroupName(group);
  const teams = (standings.teams ?? [])
    .filter((team) => team.istGroup === name)
    .map(teamOf)
    .toSorted((first, second) => first.rank - second.rank);
  if (teams.length === 0) {
    throw new Error(
      `The NBA has no ${name} table for ${standings.seasonYear} yet.`
    );
  }
  return { asOf: Date.now(), group, season: standings.seasonYear, teams };
}

/**
The NBA Cup's six groups of five, three per conference.
*/
export const CUP_GROUPS = [
  "east-a",
  "east-b",
  "east-c",
  "west-a",
  "west-b",
  "west-c",
] as const;

export type CupGroup = (typeof CUP_GROUPS)[number];

/**
"west-a" reads "West Group A", as the NBA writes it.
*/
export function cupGroupName(group: CupGroup): string {
  const [conference, letter] = group.split("-", 2);
  return `${conference.charAt(0).toUpperCase()}${conference.slice(1)} Group ${letter.toUpperCase()}`;
}

/**
The words a group's name can carry beyond its conference and letter, and everything that isn't a letter.
*/
const FILLER = /\b(?:the|conference|group)\b|ern\b|[^a-z]/gu;

/**
"west-a", "West Group A" and "Western Conference Group A" all read "west-a". Null when it names no group.
*/
export function parseCupGroup(value: string): CupGroup | null {
  const compact = value.toLowerCase().replaceAll(FILLER, "");
  return CUP_GROUPS.find((group) => group.replace("-", "") === compact) ?? null;
}

/**
One team's row in a group.
*/
export interface CupTeam {
  /**
  Its place in the group, 1 first.
  */
  rank: number;
  /**
  e.g. "Mavericks".
  */
  name: string;
  /**
  e.g. "DAL".
  */
  abbreviation: string;
  /**
  The team's logo for a light background, a square PNG.
  */
  logo: string;
  /**
  The same logo drawn for a dark background.
  */
  logoDark: string;
  wins: number;
  losses: number;
  /**
  Points scored and allowed in the group's games, and the difference.
  */
  pointsFor: number;
  pointsAgainst: number;
  difference: number;
}

/**
One NBA Cup group's table.
*/
export interface CupGroupData {
  group: CupGroup;
  /**
  e.g. "2026-27".
  */
  season: string;
  teams: CupTeam[];
  /**
  Unix time in milliseconds the table was read.
  */
  asOf: number;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeCupGroup(data: CupGroupData): string {
  const name = `NBA Cup ${cupGroupName(data.group)}, ${data.season}`;
  const [leader] = data.teams;
  const lead = leader
    ? `: the ${leader.name} lead at ${leader.wins}-${leader.losses}`
    : "";
  return `${name}${lead}.`;
}

import { getCupGroup } from "@/features/nba-cup/nba-cup-queries";
import { errorMessage, parseCupGroup } from "@/features/nba-cup/nba-cup-schema";

const CACHE = "public, s-maxage=60, stale-while-revalidate=300";

const UPSTREAM_FAILED = 502;

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const group = parseCupGroup(searchParams.get("group") ?? "");
  if (!group) {
    return Response.json(
      {
        error:
          'Pass an NBA Cup group: "east-a", "east-b", "east-c", "west-a", "west-b" or "west-c".',
      },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getCupGroup(group), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    return Response.json(
      { error: errorMessage(error, "NBA Cup lookup failed.") },
      { status: UPSTREAM_FAILED }
    );
  }
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;
